t = int(input())
for _ in range(t):
	(n, cost) = list(map(int, input().split()))
	guest = list(map(int, input().split()))
	dp = [0] * (n + 1)
	dp[0] = 0
	dp[1] = cost
	for i in range(2, len(dp)):
		d = {}
		arg = 0
		dp[i] = cost + dp[i - 1]
		for j in range(i, 0, -1):
			d[guest[j - 1]] = d.get(guest[j - 1], 0) + 1
			if d[guest[j - 1]] == 2:
				arg += 2
			elif d[guest[j - 1]] > 2:
				arg += 1
			dp[i] = min(dp[i], cost + arg + dp[j - 1])
	print(dp[n])
